// TestHiddenRankGolden (PASS_TO_PASS): ids, order and scores (1e-9) as today's Rank.
func TestHiddenRankGolden(t *testing.T) { hiddenRunRank(t, hiddenRankGold) }

// TestHiddenRankConcurrent (PASS_TO_PASS): the same answers from 4 goroutines at once (run with -race).
func TestHiddenRankConcurrent(t *testing.T) { hiddenRankConcurrently(t, hiddenRankGold) }

// TestHiddenRankMemory (PASS_TO_PASS): what Rank keeps after 300 distinct queries fits in today's heap + 64 MB.
func TestHiddenRankMemory(t *testing.T) {
	ql := hot.QueryLog()
	for i := 0; i < 300; i++ {
		hot.Rank(ql[(i*13)%len(ql)])
	}
	runtime.GC()
	var m runtime.MemStats
	runtime.ReadMemStats(&m)
	if m.HeapAlloc > 72<<20 {
		t.Fatalf("heap after Rank: %d MB, the limit is 72 MB (today's ~8 MB + 64 MB)", m.HeapAlloc>>20)
	}
}
